using System.Text.Json.Nodes;
using System.Text.Json.Serialization;

namespace LINGYUN.Abp.OpenObserve.Models.Dashboard;

/// <summary>
/// Dashboard panel operation response
/// </summary>
public class DashboardPanelResponse
{
    /// <summary>
    /// Panel definition (including id and layout generated by the server)
    /// </summary>
    [JsonPropertyName("panel")]
    public JsonNode? Panel { get; set; }

    /// <summary>
    /// New dashboard hash
    /// </summary>
    /// <remarks>
    /// Used for the next request of the chain operation
    /// </remarks>
    [JsonPropertyName("hash")]
    public string? Hash { get; set; }

    /// <summary>
    /// Page label identification
    /// </summary>
    [JsonPropertyName("tabId")]
    public string? TabId { get; set; }
}
